 "content": "def transform(grid):
    """Shear non-background cells left by their vertical distance to the bottom edge."""
    out = [[0 for _ in row] for row in grid]
    occupied_rows = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    if not occupied_rows:
        return out
    bottom = max(occupied_rows)
    height, width = len(grid), len(grid[0])
    for r, row in enumerate(grid):
        shift = bottom - r
        for c, value in enumerate(row):
            if value != 0:
                nc = c - shift
                if 0 <= nc < width:
                    out[r][nc] = value
    return out

if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
